<?php
if (!defined('ABSPATH')) exit;
function cad_contact_form(){if(!empty($_POST['cad_contact_nonce'])&&wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['cad_contact_nonce'])),'cad_contact')){$name=sanitize_text_field(wp_unslash($_POST['name']??''));$email=sanitize_email(wp_unslash($_POST['email']??''));$message=sanitize_textarea_field(wp_unslash($_POST['message']??''));if($name&&is_email($email)&&$message){wp_mail(get_option('admin_email'),'Website enquiry from '.$name,"Email: $email\n\n$message");echo '<p class="cad-success">Thanks—your enquiry has been sent.</p>';}}
ob_start();?><form class="cad-form" method="post"><p><label>Name<input required name="name"></label></p><p><label>Email<input required type="email" name="email"></label></p><p><label>Message<textarea required name="message" rows="5"></textarea></label></p><?php wp_nonce_field('cad_contact','cad_contact_nonce');?><button class="button" type="submit">Send enquiry</button></form><?php return ob_get_clean();}
add_shortcode('cad_contact_form','cad_contact_form');
function cad_register_form(){if(is_user_logged_in())return '<p>You are already logged in.</p>';ob_start();if(!empty($_POST['cad_register_nonce'])&&wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['cad_register_nonce'])),'cad_register')){$email=sanitize_email(wp_unslash($_POST['email']??''));$pass=(string)($_POST['password']??'');$name=sanitize_text_field(wp_unslash($_POST['name']??''));if(is_email($email)&&strlen($pass)>=8&&!email_exists($email)){ $id=wp_create_user($email,$pass,$email);wp_update_user(['ID'=>$id,'display_name'=>$name]);wp_set_auth_cookie($id);wp_safe_redirect(home_url('/dashboard/'));exit;}echo '<p class="cad-error">Use a valid unused email and password of at least 8 characters.</p>';}?><form class="cad-form" method="post"><p><label>Name<input required name="name"></label></p><p><label>Email<input required type="email" name="email"></label></p><p><label>Password<input required minlength="8" type="password" name="password"></label></p><?php wp_nonce_field('cad_register','cad_register_nonce');?><button class="button">Create account</button></form><?php return ob_get_clean();}
add_shortcode('cad_register','cad_register_form');
